const lesson4Data={"title":"你想要哪件？","pinyin":"Nǐ xiǎng yào nǎ jiàn?","vi":"Bạn muốn lấy chiếc nào?","rows":[["买","mǎi","mua","我想买一件衬衫。","Wǒ xiǎng mǎi yí jiàn chènshān.","Tôi muốn mua một chiếc áo sơ mi."],["衣服","yīfu","quần áo","这件衣服很好看。","Zhè jiàn yīfu hěn hǎokàn.","Bộ quần áo này rất đẹp."],["件","jiàn","chiếc; cái (lượng từ)","我买了两件衣服。","Wǒ mǎi le liǎng jiàn yīfu.","Tôi đã mua hai chiếc áo."],["衬衫","chènshān","áo sơ mi","这件衬衫多少钱？","Zhè jiàn chènshān duōshao qián?","Chiếc áo sơ mi này bao nhiêu tiền?"],["颜色","yánsè","màu sắc","你喜欢什么颜色？","Nǐ xǐhuan shénme yánsè?","Bạn thích màu gì?"],["黑","hēi","đen","我想试一下黑色的。","Wǒ xiǎng shì yíxià hēisè de.","Tôi muốn thử cái màu đen."],["蓝","lán","xanh lam","这双鞋有没有蓝色的？","Zhè shuāng xié yǒu méiyǒu lánsè de?","Đôi giày này có màu xanh lam không?"],["红","hóng","đỏ","我喜欢红色的衬衫。","Wǒ xǐhuan hóngsè de chènshān.","Tôi thích áo sơ mi màu đỏ."],["试","shì","thử","我可以试一下吗？","Wǒ kěyǐ shì yíxià ma?","Tôi thử một chút được không?"],["穿","chuān","mặc; mang (giày)","您穿什么号的？","Nín chuān shénme hào de?","Bạn mặc cỡ nào?"],["号","hào","cỡ; số","我穿三十八号的鞋。","Wǒ chuān sānshíbā hào de xié.","Tôi mang giày cỡ 38."],["觉得","juéde","cảm thấy; cho rằng","你觉得这件怎么样？","Nǐ juéde zhè jiàn zěnmeyàng?","Bạn thấy chiếc này thế nào?"],["合适","héshì","vừa; phù hợp","这双鞋大小很合适。","Zhè shuāng xié dàxiǎo hěn héshì.","Đôi giày này có kích cỡ rất vừa."],["不太","bú tài","không…lắm","我觉得不太合适。","Wǒ juéde bú tài héshì.","Tôi thấy không vừa lắm."],["双","shuāng","đôi; cặp","我想买一双鞋。","Wǒ xiǎng mǎi yì shuāng xié.","Tôi muốn mua một đôi giày."],["鞋","xié","giày","这双鞋很漂亮。","Zhè shuāng xié hěn piàoliang.","Đôi giày này rất đẹp."],["贵","guì","đắt","太贵了，可以便宜一点儿吗？","Tài guì le, kěyǐ piányi yìdiǎnr ma?","Đắt quá, có thể rẻ hơn một chút không?"],["大小","dàxiǎo","kích cỡ","这件衣服大小合适。","Zhè jiàn yīfu dàxiǎo héshì.","Chiếc áo này có kích cỡ vừa."],["不错","búcuò","khá tốt; không tệ","颜色也不错。","Yánsè yě búcuò.","Màu sắc cũng khá đẹp."]],"dialogues":[["01 · Thử áo sơ mi",[["营业员","先生，您想买什么衣服？","Xiānsheng, nín xiǎng mǎi shénme yīfu?","Thưa anh, anh muốn mua loại quần áo nào?"],["田中","我想买一件衬衫。","Wǒ xiǎng mǎi yí jiàn chènshān.","Tôi muốn mua một chiếc áo sơ mi."],["营业员","好的，我们有黑色的、红色的和蓝色的，您可以都试一下。","Hǎo de, wǒmen yǒu hēisè de, hóngsè de hé lánsè de, nín kěyǐ dōu shì yíxià.","Vâng, chúng tôi có màu đen, đỏ và xanh lam, anh có thể thử tất cả."],["田中","我想试一下黑色的和红色的。","Wǒ xiǎng shì yíxià hēisè de hé hóngsè de.","Tôi muốn thử chiếc màu đen và màu đỏ."],["营业员","好的，您穿什么号的？","Hǎo de, nín chuān shénme hào de?","Vâng, anh mặc cỡ nào?"],["田中","我穿大号的。","Wǒ chuān dà hào de.","Tôi mặc cỡ lớn."],["营业员","给您。","Gěi nín.","Của anh đây."],["田中","谢谢。","Xièxie.","Cảm ơn."],["营业员","怎么样？您觉得哪件合适？","Zěnmeyàng? Nín juéde nǎ jiàn héshì?","Thế nào ạ? Anh thấy chiếc nào vừa?"],["田中","我觉得都不太合适。谢谢。","Wǒ juéde dōu bú tài héshì. Xièxie.","Tôi thấy cả hai đều không vừa lắm. Cảm ơn."],["营业员","不客气！","Bú kèqi!","Không có gì!"]]],["02 · Mua giày và trả giá",[["美京","请问，这双鞋有没有蓝色的？","Qǐngwèn, zhè shuāng xié yǒu méiyǒu lánsè de?","Xin hỏi đôi giày này có màu xanh lam không?"],["营业员","没有蓝的，只有黑的。","Méiyǒu lán de, zhǐ yǒu hēi de.","Không có màu xanh, chỉ có màu đen."],["美京","我可以试一下黑的吗？","Wǒ kěyǐ shì yíxià hēi de ma?","Tôi thử đôi màu đen được không?"],["营业员","可以。您穿多大号的？","Kěyǐ. Nín chuān duō dà hào de?","Được ạ. Chị mang cỡ bao nhiêu?"],["美京","我穿38号的。","Wǒ chuān sānshíbā hào de.","Tôi mang cỡ 38."],["营业员","好的，请等一下。……给您。","Hǎo de, qǐng děng yíxià. Gěi nín.","Vâng, xin chờ chút. …Của chị đây."],["美京","谢谢。……这双鞋大小很合适，颜色也不错。多少钱？","Xièxie. Zhè shuāng xié dàxiǎo hěn héshì, yánsè yě búcuò. Duōshao qián?","Cảm ơn. …Đôi này kích cỡ rất vừa, màu cũng đẹp. Bao nhiêu tiền?"],["营业员","450块。","Sìbǎi wǔshí kuài.","450 tệ."],["美京","太贵了，可以便宜一点儿吗？","Tài guì le, kěyǐ piányi yìdiǎnr ma?","Đắt quá, có thể rẻ hơn một chút không?"],["营业员","可以，400块怎么样？","Kěyǐ, sìbǎi kuài zěnmeyàng?","Được, 400 tệ thế nào?"],["美京","再便宜一点儿吧！350怎么样？","Zài piányi yìdiǎnr ba! Sānbǎi wǔshí zěnmeyàng?","Rẻ thêm một chút nữa nhé! 350 thế nào?"],["营业员","行。您还想买什么？","Xíng. Nín hái xiǎng mǎi shénme?","Được. Chị còn muốn mua gì nữa?"]]]],"reading":"李美京、黄文丽和海伦是好朋友，她们平时常常一起学习，周末有时候一起看电影，一起喝咖啡。这个星期天，她们一起去买衣服。李美京想买衬衫，她不知道买什么颜色的。黄色的那件，她觉得太大了，红色的那件，她觉得不错。黄文丽想买一条裤子，她喜欢那条黑色的，可是觉得太贵了，想买那条蓝色的，又觉得大小不合适。海伦买了一双白色的鞋，很好看，也不贵，她很高兴。","exercises":{"vocab":[["请问，这（　）衬衫多少钱？","件","衬衫 dùng lượng từ 件."],["我想买一双（　）。","鞋","鞋 đi với 双."],["我（　）这个菜不好吃。","觉得","觉得: cảm thấy, cho rằng."],["我喜欢红色，你喜欢什么（　）？","颜色","颜色: màu sắc."],["什么？500块？太（　）了！","贵","太贵了: đắt quá."]],"reading":[["她们一起去买（　）。","衣服","衣服: quần áo."],["李美京想买一（　）衬衫。","件","一件衬衫."],["黄色的那件，她（　）太大了。","觉得","她觉得: cô ấy thấy."],["红色的那件，她觉得（　）。","不错","Cô ấy thấy chiếc đỏ khá tốt."],["又觉得大小不（　）。","合适","Chiếc quần xanh không vừa kích cỡ."],["海伦买了一（　）白色的鞋。","双","一双鞋: một đôi giày."]],"choose":[["这件衣服太大了，有小（　）的吗？","号","小号: cỡ nhỏ."],["我们明天（　）去看电影，好吗？","一起","一起: cùng nhau."],["我试（　）这件衬衫，可以吗？","一下","试一下: thử một chút."],["太贵了，可以便宜（　）吗？","一点儿","便宜一点儿: rẻ hơn một chút."]],"comprehension":[["她们三个人周末一起做什么？",["常常一起买衣服","有时候一起看电影","有时候一起打球"],1],["李美京为什么不买黄色的衬衫？",["她觉得太大了","她觉得不漂亮","她觉得贵了"],0],["黄文丽为什么不买蓝色的裤子？",["她觉得太大了","她觉得不合适","她觉得贵了"],1],["海伦买的鞋怎么样？",["大小合适，不太漂亮","便宜，大小不太合适","很合适、漂亮，也不贵"],2]]},"aliases":{"颜色":["色"]}};
